class Solution:
    def getSum(self, first: int, second: int) -> int:
        mask = 0xFFFFFFFF
        signed_max = 0x7FFFFFFF
        while second:
            first, second = (first ^ second) & mask, ((first & second) << 1) & mask
        return first if first <= signed_max else ~(first ^ mask)

